namespace Mapepire.EntityFrameworkCore.Update.Internal;

/// <summary>
/// Generates INSERT/UPDATE/DELETE statements for Db2 for i.
/// </summary>
/// <remarks>
/// Db2 for i has no RETURNING clause. Database-generated values on insert are read back with
/// <c>SELECT ... FROM FINAL TABLE (INSERT ...)</c>. UPDATE and DELETE are plain statements; the number
/// of affected rows (used for optimistic concurrency checks) is read from the statement's update count by
/// <see cref="MapepireModificationCommandBatch"/>. Values generated by the database on UPDATE are not read back.
/// </remarks>
public class MapepireUpdateSqlGenerator(UpdateSqlGeneratorDependencies dependencies) : UpdateSqlGenerator(dependencies)
{
    /// <inheritdoc />
    public override ResultSetMapping AppendInsertOperation(
        StringBuilder commandStringBuilder,
        IReadOnlyModificationCommand command,
        int commandPosition,
        out bool requiresTransaction)
    {
        var name = command.TableName;
        var schema = command.Schema;
        var writeOperations = command.ColumnModifications.Where(o => o.IsWrite).ToList();
        var readOperations = command.ColumnModifications.Where(o => o.IsRead).ToList();

        requiresTransaction = false;

        if (readOperations.Count > 0)
        {
            commandStringBuilder.Append("SELECT ");
            for (var i = 0; i < readOperations.Count; i++)
            {
                if (i > 0)
                {
                    commandStringBuilder.Append(", ");
                }

                SqlGenerationHelper.DelimitIdentifier(commandStringBuilder, readOperations[i].ColumnName);
            }

            commandStringBuilder.Append(" FROM FINAL TABLE (");
            AppendInsertCommandHeader(commandStringBuilder, name, schema, writeOperations);
            AppendValuesHeader(commandStringBuilder, writeOperations);
            AppendValues(commandStringBuilder, name, schema, writeOperations);
            commandStringBuilder.Append(')').AppendLine(SqlGenerationHelper.StatementTerminator);
            return ResultSetMapping.LastInResultSet;
        }

        AppendInsertCommandHeader(commandStringBuilder, name, schema, writeOperations);
        AppendValuesHeader(commandStringBuilder, writeOperations);
        AppendValues(commandStringBuilder, name, schema, writeOperations);
        commandStringBuilder.AppendLine(SqlGenerationHelper.StatementTerminator);
        return ResultSetMapping.NoResults;
    }

    /// <inheritdoc />
    public override ResultSetMapping AppendUpdateOperation(
        StringBuilder commandStringBuilder,
        IReadOnlyModificationCommand command,
        int commandPosition,
        out bool requiresTransaction)
    {
        var writeOperations = command.ColumnModifications.Where(o => o.IsWrite).ToList();
        var conditionOperations = command.ColumnModifications.Where(o => o.IsCondition).ToList();

        requiresTransaction = false;
        AppendUpdateCommand(
            commandStringBuilder, command.TableName, command.Schema, writeOperations, [], conditionOperations,
            appendReturningOneClause: false);
        return ResultSetMapping.NoResults;
    }

    /// <inheritdoc />
    public override ResultSetMapping AppendDeleteOperation(
        StringBuilder commandStringBuilder,
        IReadOnlyModificationCommand command,
        int commandPosition,
        out bool requiresTransaction)
    {
        var conditionOperations = command.ColumnModifications.Where(o => o.IsCondition).ToList();

        requiresTransaction = false;
        AppendDeleteCommand(
            commandStringBuilder, command.TableName, command.Schema, [], conditionOperations,
            appendReturningOneClause: false);
        return ResultSetMapping.NoResults;
    }

    /// <inheritdoc />
    protected override void AppendValuesHeader(StringBuilder commandStringBuilder, IReadOnlyList<IColumnModification> operations)
    {
        commandStringBuilder.AppendLine();
        // Db2 for i has no "DEFAULT VALUES"; VALUES (DEFAULT) inserts a row of defaults.
        commandStringBuilder.Append(operations.Count > 0 ? "VALUES " : "VALUES (DEFAULT)");
    }

    /// <inheritdoc />
    public override string GenerateNextSequenceValueOperation(string name, string? schema)
    {
        var sb = new StringBuilder();
        AppendNextSequenceValueOperation(sb, name, schema);
        return sb.ToString();
    }

    /// <inheritdoc />
    public override void AppendNextSequenceValueOperation(StringBuilder commandStringBuilder, string name, string? schema)
    {
        commandStringBuilder.Append("VALUES NEXT VALUE FOR ");
        SqlGenerationHelper.DelimitIdentifier(commandStringBuilder, name, schema);
    }

    /// <inheritdoc />
    public override string GenerateObtainNextSequenceValueOperation(string name, string? schema)
    {
        var sb = new StringBuilder();
        AppendObtainNextSequenceValueOperation(sb, name, schema);
        return sb.ToString();
    }

    /// <inheritdoc />
    public override void AppendObtainNextSequenceValueOperation(StringBuilder commandStringBuilder, string name, string? schema)
    {
        commandStringBuilder.Append("NEXT VALUE FOR ");
        SqlGenerationHelper.DelimitIdentifier(commandStringBuilder, name, schema);
    }
}

/// <summary>
/// Executes one modification command per round trip and validates the affected row count of UPDATE and
/// DELETE statements, which Db2 for i cannot return as a result set.
/// </summary>
public class MapepireModificationCommandBatch(ModificationCommandBatchFactoryDependencies dependencies)
    : AffectedCountModificationCommandBatch(dependencies, maxBatchSize: 1)
{
    /// <inheritdoc />
    protected override void Consume(RelationalDataReader reader)
    {
        CheckRowsAffected(reader);
        base.Consume(reader);
    }

    /// <inheritdoc />
    protected override async Task ConsumeAsync(RelationalDataReader reader, CancellationToken cancellationToken = default)
    {
        CheckRowsAffected(reader);
        await base.ConsumeAsync(reader, cancellationToken).ConfigureAwait(false);
    }

    private void CheckRowsAffected(RelationalDataReader reader)
    {
        if (ModificationCommands.Count != 1 || ResultSetMappings[0].HasFlag(ResultSetMapping.HasResultRow))
        {
            return;
        }

        var command = ModificationCommands[0];
        if (command.EntityState is not (EntityState.Modified or EntityState.Deleted))
        {
            return;
        }

        var rowsAffected = reader.DbDataReader.RecordsAffected;
        if (rowsAffected != 1)
        {
            ThrowAggregateUpdateConcurrencyException(reader, commandIndex: 1, expectedRowsAffected: 1, rowsAffected: Math.Max(rowsAffected, 0));
        }
    }
}

/// <summary>Creates <see cref="MapepireModificationCommandBatch"/> instances.</summary>
public class MapepireModificationCommandBatchFactory(ModificationCommandBatchFactoryDependencies dependencies)
    : IModificationCommandBatchFactory
{
    /// <inheritdoc />
    public virtual ModificationCommandBatch Create() => new MapepireModificationCommandBatch(dependencies);
}
